// Generated by AI (UnitTest MCP)
import { execFileSync, spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterEach, describe, expect, it } from "vitest";

const guard = join(
  dirname(fileURLToPath(import.meta.url)),
  "../../../scripts/adr-number-guard.mjs"
);
const temporaryDirectories = [];
const gitRepositoryVariables = [
  "GIT_DIR",
  "GIT_WORK_TREE",
  "GIT_COMMON_DIR",
  "GIT_INDEX_FILE",
  "GIT_OBJECT_DIRECTORY",
  "GIT_ALTERNATE_OBJECT_DIRECTORIES",
];

const isolatedGitEnvironment = () => {
  const isolated = { ...process.env, PRE_COMMIT_ALLOW_NO_CONFIG: "1" };
  for (const variable of gitRepositoryVariables) delete isolated[variable];
  return isolated;
};

afterEach(() => {
  for (const directory of temporaryDirectories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

const git = (cwd, args) =>
  execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    stdio: "pipe",
    env: isolatedGitEnvironment(),
  }).trim();

const writeAdr = (repo, name) => {
  mkdirSync(join(repo, "docs", "adr"), { recursive: true });
  writeFileSync(join(repo, "docs", "adr", name), `# ${name}\n`);
  return `docs/adr/${name}`;
};

/** A repo whose `other` branch already claims ADR-0042. */
const repoWithRivalAdr = () => {
  const repo = mkdtempSync(join(tmpdir(), "mindleak-adr-guard-"));
  temporaryDirectories.push(repo);
  git(repo, ["init", "-b", "main"]);
  git(repo, ["config", "user.name", "ADR Guard Test"]);
  git(repo, ["config", "user.email", "adr-guard@example.invalid"]);
  writeFileSync(join(repo, "base.txt"), "base\n");
  git(repo, ["add", "base.txt"]);
  git(repo, ["commit", "-m", "base"]);

  git(repo, ["checkout", "-b", "other"]);
  const rival = writeAdr(repo, "0042-their-decision.md");
  git(repo, ["add", rival]);
  git(repo, ["commit", "-m", "their adr"]);
  git(repo, ["checkout", "main"]);
  return repo;
};

const runGuard = (repo, args) =>
  spawnSync(process.execPath, [guard, ...args], {
    cwd: repo,
    encoding: "utf8",
    env: isolatedGitEnvironment(),
  });

describe("adr-number-guard", () => {
  it("refuses a number already claimed on a branch you cannot see", () => {
    // The whole failure mode: your working tree looks clean, because the
    // conflict lives on a sibling branch.
    const repo = repoWithRivalAdr();
    const mine = writeAdr(repo, "0042-my-decision.md");

    const result = runGuard(repo, [mine]);

    expect(result.status).toBe(1);
    expect(result.stderr).toMatch(/ADR-0042 is already claimed/);
    expect(result.stderr).toMatch(/0042-their-decision\.md {2}on other/);
    expect(result.stderr).toMatch(/Renumber to ADR-0043/);
  }, 30_000);

  it("suggests the next number that is actually free, not merely the next one", () => {
    const repo = repoWithRivalAdr();
    git(repo, ["checkout", "other"]);
    const alsoTaken = writeAdr(repo, "0043-another-decision.md");
    git(repo, ["add", alsoTaken]);
    git(repo, ["commit", "-m", "another adr"]);
    git(repo, ["checkout", "main"]);

    const mine = writeAdr(repo, "0042-my-decision.md");
    const result = runGuard(repo, [mine]);

    expect(result.status).toBe(1);
    expect(result.stderr).toMatch(/Renumber to ADR-0044/);
  }, 30_000);

  it("allows the same file already on your own branch", () => {
    // Re-committing or amending your own ADR is not a collision.
    const repo = repoWithRivalAdr();
    git(repo, ["checkout", "other"]);
    const result = runGuard(repo, ["docs/adr/0042-their-decision.md"]);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
  }, 30_000);

  it("allows a free number", () => {
    const repo = repoWithRivalAdr();
    const mine = writeAdr(repo, "0099-unclaimed.md");

    const result = runGuard(repo, [mine]);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
  }, 30_000);

  it("ignores files that are not numbered ADRs", () => {
    const repo = repoWithRivalAdr();
    const result = runGuard(repo, ["docs/adr/README.md", "CHANGELOG.md"]);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
  }, 30_000);
});
